package erratum

import "errors"

// Use opens a resource with the given opener, calls Frob(input) on it, and
// guarantees the resource is closed exactly once.
//
// While opening, TransientError values are retried; any other error is
// returned. If Frob panics with a FrobError, the resource's Defrob method is
// called with the FrobError's defrobTag before the resource is closed, and
// the FrobError is returned. Any other error-typed panic is returned as-is.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	var err error
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var transientErr TransientError
		if !errors.As(err, &transientErr) {
			return err
		}
	}

	defer resource.Close()

	var useErr error
	defer func() {
		switch r := recover(); r := r.(type) {
		case FrobError:
			resource.Defrob(r.defrobTag)
			useErr = r
		case error:
			useErr = r
		}
	}()

	resource.Frob(input)
	return useErr
}

